use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdecltrait! {
# [doc = " Methods for determining displayed width of Unicode characters."] pub trait UnicodeWidthChar : private :: Sealed { # [doc = " Returns the character's displayed width in columns, or `None` if the"] # [doc = " character is a control character."] # [doc = ""] # [doc = " This function treats characters in the Ambiguous category according"] # [doc = " to [Unicode Standard Annex #11](http://www.unicode.org/reports/tr11/)"] # [doc = " as 1 column wide. This is consistent with the recommendations for non-CJK"] # [doc = " contexts, or when the context cannot be reliably determined."] fn width (self) -> Option < usize > ; # [doc = " Returns the character's displayed width in columns, or `None` if the"] # [doc = " character is a control character."] # [doc = ""] # [doc = " This function treats characters in the Ambiguous category according"] # [doc = " to [Unicode Standard Annex #11](http://www.unicode.org/reports/tr11/)"] # [doc = " as 2 columns wide. This is consistent with the recommendations for"] # [doc = " CJK contexts."] # [cfg (feature = "cjk")] fn width_cjk (self) -> Option < usize > ; }
}